<?php
/** Current relationship integrity. Empty current-work registries are valid before MD-B00 opens. */
function rows($p){$o=array();$f=fopen($p,'r');$h=fgetcsv($f);if(isset($h[0]))$h[0]=preg_replace('/^\xEF\xBB\xBF/','',$h[0]);while(($r=fgetcsv($f))!==false){$a=array();foreach($h as $i=>$k)$a[$k]=isset($r[$i])?trim($r[$i]):'';$o[]=$a;}fclose($f);return $o;}
$md=realpath(dirname(__DIR__,3));$rec=rows($md.'/records/WORK_RECORD_REGISTRY.csv');$rel=rows($md.'/records/WORK_RELATIONSHIP_REGISTRY.csv');$errors=array();$ids=array();$attempt=array();foreach($rec as $r){if(isset($ids[$r['record_id']]))$errors[]='duplicate record '.$r['record_id'];$ids[$r['record_id']]=$r;if($r['attempt_id']!==''&&$r['work_id']!==$r['attempt_id'])$errors[]='work identity mismatch '.$r['record_id'];if($r['attempt_id']!==''&&!preg_match('/^MD-B\d{2}-A\d{3}$/',$r['attempt_id']))$errors[]='bad attempt '.$r['record_id'];if($r['attempt_id']!==''){if(isset($attempt[$r['attempt_id']])&&$attempt[$r['attempt_id']]!==array($r['stage_id'],$r['baseline_id']))$errors[]='attempt identity split '.$r['attempt_id'];$attempt[$r['attempt_id']]=array($r['stage_id'],$r['baseline_id']);}}
$rid=array();foreach($rel as $r){if(isset($rid[$r['relationship_id']]))$errors[]='duplicate relationship '.$r['relationship_id'];$rid[$r['relationship_id']]=1;if(!isset($ids[$r['source_record_id']])||!isset($ids[$r['target_record_id']]))$errors[]='unresolved relationship '.$r['relationship_id'];}
$out=array('gate'=>'MarketDataRelationshipIntegrityGate','status'=>$errors?'FAIL':'PASS','records'=>count($rec),'relationships'=>count($rel),'errors'=>$errors,'generated_at'=>date(DATE_ATOM));file_put_contents($md.'/records/evidence/MD_RELATIONSHIP_INTEGRITY_GATE_LATEST.json',json_encode($out,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES).PHP_EOL);echo json_encode($out,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES).PHP_EOL;exit($errors?1:0);
